// Verify: (std::cout << float, default flags)  ==  printf("%g", (double)f)
#include <cstdio>
#include <cstdint>
#include <cstring>
#include <cmath>
#include <sstream>
#include <iostream>
#include <string>

static inline float bits2f(uint32_t b){ float f; memcpy(&f,&b,4); return f; }

int main(){
    uint64_t checked=0, mismatch=0;
    uint32_t x = 0x12345678u;
    // 1) exhaustive-ish structured set: n/2^k
    for(int k=0;k<=24;k++){
        long lim = (1L<<k); if(lim>4096) lim=4096;
        for(long n=0;n<=lim;n++){
            float f = (float)n / (float)(1u<<k);
            char buf[64]; snprintf(buf,sizeof buf,"%g",(double)f);
            std::ostringstream os; os << f;
            checked++;
            if(os.str()!=buf){ if(mismatch<20) printf("MISMATCH n/2^k n=%ld k=%d printf=%s cout=%s\n",n,k,buf,os.str().c_str()); mismatch++; }
        }
    }
    // 2) random sweep
    for(long i=0;i<400000;i++){
        x ^= x<<13; x ^= x>>17; x ^= x<<5;
        float f = bits2f(x);
        if(std::isnan(f)||std::isinf(f)) continue;
        char buf[64]; snprintf(buf,sizeof buf,"%g",(double)f);
        std::ostringstream os; os << f;
        checked++;
        if(os.str()!=buf){ if(mismatch<20) printf("MISMATCH bits=%08x printf=%s cout=%s\n",x,buf,os.str().c_str()); mismatch++; }
    }
    printf("checked=%llu mismatch=%llu\n",(unsigned long long)checked,(unsigned long long)mismatch);
    return 0;
}
EOF
