/* gen_gcorpus.c -- generate a differential-testing corpus for
 *
 *     printf("%g", (double)f)      for f : float
 *
 * which is exactly what `std::cout << someFloat` produces with default
 * stream flags (verified separately by verify_cout_vs_printf.cpp).
 *
 * Output: one TSV line per float value
 *     <8 lowercase hex digits of the u32 bit pattern>\t<printf("%g") output>
 *
 * NaN and Inf bit patterns are skipped.
 *
 * Build:  gcc -O2 -o gen_gcorpus gen_gcorpus.c
 * Run:    ./gen_gcorpus > gcorpus.tsv
 *
 * Families emitted (see main()):
 *   F1  every n/2^k with k in 0..24, n in 0..min(2^k,4096)   <- the load_factor lattice
 *   F2  EXACT decimal ties at 6 significant digits.  These are enumerated
 *       *constructively and exhaustively* (then subsampled), see tie_families().
 *   F3  the +-1 ulp neighbours of ties (just-below / just-above a tie)
 *   F4  %g style-switch straddlers: X < -4 and X >= 6 boundaries, the
 *       "rounding changes the exponent and therefore the style" cases,
 *       every power of ten and every 9.999995e{k} carry boundary +- 6 ulp
 *   F5  hand-picked specials: +-0, subnormals, FLT_MIN, FLT_MAX, 1e-45, ...
 *   F6  deterministic xorshift32 pseudo-random sweep of 200000 bit patterns
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <float.h>

/* ------------------------------------------------------------------ */
/* output                                                              */
/* ------------------------------------------------------------------ */
static unsigned long long g_emitted = 0;
static unsigned long long g_skipped_nan = 0;
static unsigned long long g_inexact = 0;   /* must stay 0 */

static float b2f(uint32_t b) { float f; memcpy(&f, &b, 4); return f; }
static uint32_t f2b(float f) { uint32_t b; memcpy(&b, &f, 4); return b; }

static void emit_bits(uint32_t b)
{
    if (((b >> 23) & 0xFFu) == 0xFFu) { g_skipped_nan++; return; }  /* NaN/Inf */
    float f = b2f(b);
    printf("%08x\t%g\n", b, (double)f);
    g_emitted++;
}

static void emit_f(float f) { emit_bits(f2b(f)); }

/* emit b-1, b, b+1 (staying inside finite range) */
static void emit_neighbourhood(uint32_t b, int radius)
{
    for (int d = -radius; d <= radius; d++) {
        int64_t nb = (int64_t)b + d;
        if (nb < 0 || nb > 0xFFFFFFFFLL) continue;
        emit_bits((uint32_t)nb);
    }
}

/* ------------------------------------------------------------------ */
/* F1: the n/2^k lattice -- every value a load_factor can ever be      */
/* ------------------------------------------------------------------ */
static void family_lattice(void)
{
    for (int k = 0; k <= 24; k++) {
        long lim = 1L << k;
        if (lim > 4096) lim = 4096;
        for (long n = 0; n <= lim; n++) {
            float f = (float)n / (float)(1UL << k);
            emit_f(f);
        }
    }
    /* also the exact shapes produced by the program: size/bucket_count with
       bucket_count a power of two and size <= bucket_count */
    for (int k = 1; k <= 24; k++) {
        unsigned long bc = 1UL << k;
        unsigned long step = (bc > 4096) ? bc / 4096 : 1;
        for (unsigned long n = 0; n <= bc; n += step) {
            emit_f((float)n / (float)bc);
        }
        emit_f((float)bc / (float)bc);
    }
}

/* ------------------------------------------------------------------ */
/* F2: EXACT decimal ties at precision 6                               */
/*                                                                     */
/* Write the exact value of a finite float as  D * 10^E  with D an      */
/* integer having NO trailing zeros ("the significant digits").         */
/* Rounding to 6 significant digits is an exact tie  <=>  D has exactly */
/* 7 decimal digits and D mod 10 == 5.                                  */
/*                                                                     */
/* Every finite float is  M * 2^e  with M odd, M < 2^24.                */
/*                                                                     */
/*  (a) e >= 0 (integers).  D odd forces e == t == v5(M), so             */
/*      M = D * 5^e, D a 7-digit multiple of 5 (i.e. ending in 5).      */
/*      M < 2^24 => e = 0 (D = 1000005..9999995 step 10)                */
/*                  or e = 1 (D = 1000005..3355435 step 10, value 10*D) */
/*      e >= 2 is impossible (25*1000005 > 2^24).                       */
/*                                                                     */
/*  (b) e < 0, value = M / 2^s, s >= 1.  Then D = M * 5^s (which always */
/*      ends in 5), so the condition is 10^6 <= M*5^s <= 10^7 - 1.      */
/*      5^s <= 9999999 => s <= 10.                                      */
/*                                                                     */
/* This enumeration is COMPLETE: it is every exact 6-digit tie in the   */
/* whole binary32 format.  There are 2,260,546 of them.                 */
/* ------------------------------------------------------------------ */
#define TIE_CAP 40000L      /* max samples taken from one tie family */

/* emit a strided subsample of the arithmetic sequence first,first+step,..,last
   (inclusive), always keeping the leading and trailing EDGE members. */
#define EDGE 400L
static void strided(long first, long last, long step,
                    void (*fn)(long, int), int arg,
                    unsigned long long *counted)
{
    long count = (last - first) / step + 1;
    *counted += (unsigned long long)count;
    long stride = 1;
    if (count > TIE_CAP) stride = count / TIE_CAP + 1;
    for (long i = 0; i < count; i++) {
        if (i < EDGE || i >= count - EDGE || i % stride == 0) fn(first + i * step, arg);
    }
}

/* --- tie emitters ------------------------------------------------- */
static int g_tie_nth = 0;           /* for neighbour subsampling */
static int g_emit_neighbours = 0;

static void tie_value(double exact, int check_pow2_denom_shift)
{
    /* exact must be representable as float; verify, then emit (+ neighbours) */
    float f = (float)exact;
    if ((double)f != exact) { g_inexact++; return; }
    (void)check_pow2_denom_shift;
    uint32_t b = f2b(f);
    emit_bits(b);
    if (g_emit_neighbours && (g_tie_nth++ % 4) == 0) {
        emit_bits(b - 1u);
        emit_bits(b + 1u);
    }
    /* negatives too: sign is orthogonal but cheap to cover */
    if ((g_tie_nth % 32) == 0) emit_bits(b ^ 0x80000000u);
}

static void tie_int(long D, int t)          /* value = D * 10^t  (t = 0 or 1) */
{
    double v = (double)D;
    if (t == 1) v *= 10.0;
    tie_value(v, 0);
}

static void tie_frac(long M, int s)         /* value = M / 2^s */
{
    double v = (double)M / (double)(1UL << s);
    tie_value(v, s);
}

static unsigned long long tie_total = 0;

static void tie_families(void)
{
    /* (a) integer ties */
    strided(1000005L, 9999995L, 10L, tie_int, 0, &tie_total);   /* 900000  */
    strided(1000005L, 3355435L, 10L, tie_int, 1, &tie_total);   /* 235544  */

    /* (b) fraction ties: M odd, 10^6 <= M*5^s <= 10^7-1, s = 1..10 */
    long pow5 = 1;
    for (int s = 1; s <= 10; s++) {
        pow5 *= 5;
        long lo = (1000000L + pow5 - 1) / pow5;      /* ceil (10^6 / 5^s) */
        long hi = 9999999L / pow5;                   /* floor((10^7-1)/5^s) */
        if (lo % 2 == 0) lo++;                       /* M must be odd */
        if (hi % 2 == 0) hi--;
        if (lo > hi) continue;
        if (hi >= (1L << 24)) hi = (1L << 24) - 1;   /* M < 2^24 (never trips) */
        strided(lo, hi, 2L, tie_frac, s, &tie_total);
    }
}

/* ------------------------------------------------------------------ */
/* F4: style-switch straddlers                                         */
/* ------------------------------------------------------------------ */
static void anchor(const char *decimal, int radius)
{
    float f = strtof(decimal, NULL);
    emit_neighbourhood(f2b(f), radius);
    emit_neighbourhood(f2b(-f), radius);
}

static void family_style_switch(void)
{
    /* the two hard style boundaries, with generous neighbourhoods */
    anchor("999999.5",     3000);   /* X 5 -> 6 after rounding: f-style -> e-style */
    anchor("1e6",          3000);
    anchor("9.999995e-5",  3000);   /* X -5 -> -4 after rounding: e-style -> f-style */
    anchor("1e-4",         3000);
    anchor("1e-5",         2000);
    anchor("9.999995e-6",  2000);
    anchor("99999.5",      1000);
    anchor("100000.5",     1000);
    anchor("1234567",      1000);
    anchor("1",            2000);   /* 0.99999994 -> "1" (carry out of all 9s) */

    /* every decimal exponent: 10^k, the carry boundary 9.999995e{k},
       1.000005e{k}, 1.234565e{k}, 5.000005e{k} */
    static const char *pat[] = { "1e%d", "9.999995e%d", "1.000005e%d",
                                 "1.234565e%d", "5.000005e%d", "9.99999e%d",
                                 "1.00001e%d" };
    for (int k = -46; k <= 39; k++) {
        for (unsigned p = 0; p < sizeof pat / sizeof *pat; p++) {
            char buf[64];
            snprintf(buf, sizeof buf, pat[p], k);
            float f = strtof(buf, NULL);
            if (f == 0.0f || f != f) continue;
            emit_neighbourhood(f2b(f), 6);
        }
    }
}

/* ------------------------------------------------------------------ */
/* F5: specials                                                        */
/* ------------------------------------------------------------------ */
static void family_specials(void)
{
    static const uint32_t bits[] = {
        0x00000000u, 0x80000000u,                 /* +-0                     */
        0x00000001u, 0x80000001u, 0x00000002u, 0x00000003u, 0x00000004u,
        0x00000005u, 0x0000000Au, 0x000000FFu, 0x00001000u,
        0x007FFFFFu, 0x00800000u, 0x80800000u,    /* max subnormal, FLT_MIN  */
        0x7F7FFFFFu, 0xFF7FFFFFu,                 /* +-FLT_MAX               */
        0x3F800000u, 0xBF800000u,                 /* +-1                     */
        0x3F7FFFFFu, 0x3F800001u,
        0x4B7FFFFFu, 0x4B800000u,                 /* 2^24-1, 2^24            */
        0x3E3E0F84u,                              /* ~0.18559  */
    };
    for (unsigned i = 0; i < sizeof bits / sizeof *bits; i++) emit_bits(bits[i]);

    static const char *dec[] = {
        "0", "-0", "1e-45", "1.4013e-45", "1e-44", "3.4028235e38", "1.1754944e-38",
        "1e-5", "9.99999e-5", "9.999995e-5", "9.9999949e-5", "1e-4", "0.0001",
        "1e6", "999999", "999999.5", "1234567", "0.4453125", "0.6875", "0.34375",
        "0.5", "0.75", "0.375", "0.875", "0.4375", "0.5625", "0.28125",
        "0.78125", "0.390625", "0.488281", "0.48828125", "1e7", "1e8", "1e9",
        "0.1", "0.2", "0.3", "1.0/3", "0.33333334", "0.6666667", "123456.7",
        "1000005", "1000015", "1234565", "9999995", "8388605", "1048575",
        "10000050", "12345650", "0.0009765625", "0.001953125", "0.005859375",
        "0.009765625", "0.000446319580078125", "0.0004556179046630859375",
        "0.44433593750", "0.44482421875",
    };
    for (unsigned i = 0; i < sizeof dec / sizeof *dec; i++) {
        float f = strtof(dec[i], NULL);
        emit_f(f);
        emit_f(-f);
    }
    /* exhaustive sweep of the tiny subnormals and of the exponent-0 decade */
    for (uint32_t b = 0; b <= 4000; b++) emit_bits(b);
    for (uint32_t b = 0x3F000000u; b <= 0x3F000000u + 3000u; b++) emit_bits(b);
}

/* ------------------------------------------------------------------ */
/* F6: deterministic xorshift32 sweep                                  */
/* ------------------------------------------------------------------ */
#define XS_SEED 0x2545F491u
static void family_random(void)
{
    uint32_t x = XS_SEED;
    long produced = 0;
    while (produced < 200000) {
        x ^= x << 13; x ^= x >> 17; x ^= x << 5;
        if (((x >> 23) & 0xFFu) == 0xFFu) continue;   /* skip NaN/Inf */
        emit_bits(x);
        produced++;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    static char obuf[1 << 22];
    setvbuf(stdout, obuf, _IOFBF, sizeof obuf);

    family_lattice();

    g_emit_neighbours = 1;
    tie_families();
    g_emit_neighbours = 0;

    family_style_switch();
    family_specials();
    family_random();

    fflush(stdout);
    fprintf(stderr, "emitted=%llu  skipped_nan_inf=%llu  inexact_constructions=%llu\n"
                    "total_exact_6digit_ties_in_binary32=%llu\n",
            g_emitted, g_skipped_nan, g_inexact, tie_total);
    return g_inexact ? 1 : 0;
}

/* model_g.c -- from-scratch reference implementation of
 *
 *      printf("%g", (double)f)      for f : float,  in FE_TONEAREST
 *
 * Uses ONLY integer arithmetic on a decimal digit array (a stand-in for a
 * bignum).  No floating point formatting of any kind is used.  This is a
 * direct transcription of the numbered rules in the spec, so that validating
 * it against gcorpus.tsv validates the rules.
 *
 * Build: gcc -O2 -o model_g model_g.c
 * Run:   ./model_g gcorpus.tsv
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/* ---- tiny decimal bignum: d[0] is the MOST significant digit ---------- */
#define MAXD 256
typedef struct { unsigned char d[MAXD]; int n; } dec_t;   /* n = digit count */

static void dec_from_u32(dec_t *a, uint32_t v)
{
    char tmp[16]; int n = 0;
    if (v == 0) { a->d[0] = 0; a->n = 1; return; }
    while (v) { tmp[n++] = (char)(v % 10); v /= 10; }
    a->n = n;
    for (int i = 0; i < n; i++) a->d[i] = (unsigned char)tmp[n - 1 - i];
}

static void dec_mul_small(dec_t *a, int m)      /* a *= m  (m small) */
{
    int carry = 0;
    for (int i = a->n - 1; i >= 0; i--) {
        int p = a->d[i] * m + carry;
        a->d[i] = (unsigned char)(p % 10);
        carry = p / 10;
    }
    while (carry) {
        memmove(a->d + 1, a->d, (size_t)a->n);
        a->d[0] = (unsigned char)(carry % 10);
        carry /= 10;
        a->n++;
    }
    while (a->n > 1 && a->d[0] == 0) { memmove(a->d, a->d + 1, (size_t)--a->n); }
}

/* ---------------------------------------------------------------------- */
/* format one float bit pattern into out[] exactly as glibc %g (prec 6)    */
/* ---------------------------------------------------------------------- */
#define PREC 6

static void format_g(uint32_t bits, char *out)
{
    int sign = (int)(bits >> 31);
    int ebits = (int)((bits >> 23) & 0xFF);
    uint32_t frac = bits & 0x7FFFFF;
    char *o = out;
    if (sign) *o++ = '-';

    /* --- inf / nan (never appear in the corpus, kept for completeness) -- */
    if (ebits == 0xFF) {
        if (frac) { strcpy(o, "nan"); } else { strcpy(o, "inf"); }
        return;
    }

    /* --- exact value = m * 2^exp2 ------------------------------------- */
    uint32_t m; int exp2;
    if (ebits == 0) { m = frac;               exp2 = -149; }
    else            { m = frac | 0x800000u;   exp2 = ebits - 150; }

    unsigned char dig[PREC];   /* the 6 rounded significant digits */
    int X;                     /* decimal exponent of dig[0]       */

    if (m == 0) {                       /* Rule Z: zero */
        for (int i = 0; i < PREC; i++) dig[i] = 0;
        X = 0;
    } else {
        /* value = A * 10^(-s) with A an exact integer */
        dec_t A; dec_from_u32(&A, m);
        int s;
        if (exp2 >= 0) { s = 0;      for (int i = 0; i < exp2; i++) dec_mul_small(&A, 2); }
        else           { s = -exp2;  for (int i = 0; i < s;    i++) dec_mul_small(&A, 5); }

        int L = A.n;                 /* A has no leading zeros            */
        int X0 = L - 1 - s;          /* exponent of A's first digit       */

        if (L <= PREC) {
            for (int i = 0; i < PREC; i++) dig[i] = (i < L) ? A.d[i] : 0;
            X = X0;
        } else {
            for (int i = 0; i < PREC; i++) dig[i] = A.d[i];
            /* compare tail A.d[PREC..L-1] against 5 000...0 */
            int cmp;
            if (A.d[PREC] > 5) cmp = 1;
            else if (A.d[PREC] < 5) cmp = -1;
            else {
                cmp = 0;
                for (int i = PREC + 1; i < L; i++) if (A.d[i]) { cmp = 1; break; }
            }
            int up = (cmp > 0) || (cmp == 0 && (dig[PREC - 1] & 1));  /* ties-to-even */
            X = X0;
            if (up) {
                int i = PREC - 1;
                for (;;) {
                    if (dig[i] != 9) { dig[i]++; break; }
                    dig[i] = 0;
                    if (i == 0) {                     /* 999999 -> 1000000 */
                        dig[0] = 1;                   /* becomes 1.00000   */
                        X = X0 + 1;
                        break;
                    }
                    i--;
                }
            }
        }
    }

    /* --- style selection (on the POST-ROUNDING exponent X) ------------ */
    if (X < -4 || X >= PREC) {
        /* style e, precision PREC-1 = 5, then strip trailing zeros */
        int last = PREC - 1;
        while (last > 0 && dig[last] == 0) last--;
        *o++ = (char)('0' + dig[0]);
        if (last > 0) {
            *o++ = '.';
            for (int i = 1; i <= last; i++) *o++ = (char)('0' + dig[i]);
        }
        *o++ = 'e';
        int ax = X < 0 ? -X : X;
        *o++ = X < 0 ? '-' : '+';
        if (ax >= 100) { *o++ = (char)('0' + ax / 100); ax %= 100; }
        *o++ = (char)('0' + ax / 10);
        *o++ = (char)('0' + ax % 10);
        *o = 0;
    } else {
        /* style f, precision PREC-1-X, then strip trailing zeros + point  */
        char fr[32]; int nf = 0;
        if (X >= 0) {
            for (int i = 0; i <= X; i++) *o++ = (char)('0' + dig[i]);
            for (int i = X + 1; i < PREC; i++) fr[nf++] = (char)('0' + dig[i]);
        } else {
            *o++ = '0';
            for (int i = 0; i < -X - 1; i++) fr[nf++] = '0';
            for (int i = 0; i < PREC; i++) fr[nf++] = (char)('0' + dig[i]);
        }
        while (nf > 0 && fr[nf - 1] == '0') nf--;      /* strip trailing zeros */
        if (nf > 0) { *o++ = '.'; memcpy(o, fr, (size_t)nf); o += nf; }
        *o = 0;                                        /* point dropped if none */
    }
}

/* ---------------------------------------------------------------------- */
int main(int argc, char **argv)
{
    if (argc < 2) { fprintf(stderr, "usage: model_g corpus.tsv\n"); return 2; }
    FILE *fp = fopen(argv[1], "r");
    if (!fp) { perror(argv[1]); return 2; }
