// %g (precision 6) for f32 implemented in Rust two ways, both diffed against
// the glibc-generated corpus.
//   way A: on top of format!("{:.5e}") -- relies on Rust rounding correctly
//   way B: from scratch with a decimal bignum (u8 digit vector), no float fmt
use std::io::{BufRead, BufReader};

const P: i32 = 6;

fn render(sign: bool, dig: &[u8; 6], x: i32) -> String {
    let mut out = String::new();
    if sign { out.push('-'); }
    if x < -4 || x >= P {
        let mut last = 5usize;
        while last > 0 && dig[last] == 0 { last -= 1; }
        out.push((b'0' + dig[0]) as char);
        if last > 0 {
            out.push('.');
            for i in 1..=last { out.push((b'0' + dig[i]) as char); }
        }
        out.push('e');
        out.push(if x < 0 { '-' } else { '+' });
        let ax = x.abs();
        if ax >= 100 { out.push((b'0' + (ax / 100) as u8) as char); }
        out.push((b'0' + ((ax / 10) % 10) as u8) as char);
        out.push((b'0' + (ax % 10) as u8) as char);
    } else {
        let mut fr = String::new();
        if x >= 0 {
            for i in 0..=(x as usize) { out.push((b'0' + dig[i]) as char); }
            for i in (x as usize + 1)..6 { fr.push((b'0' + dig[i]) as char); }
        } else {
            out.push('0');
            for _ in 0..(-x - 1) { fr.push('0'); }
            for i in 0..6 { fr.push((b'0' + dig[i]) as char); }
        }
        while fr.ends_with('0') { fr.pop(); }
        if !fr.is_empty() { out.push('.'); out.push_str(&fr); }
    }
    out
}

// ---- way A -------------------------------------------------------------
fn g_via_rust_e(f: f32) -> String {
    let s = format!("{:.5e}", f);
    let b = s.as_bytes();
    let mut i = 0usize;
    let sign = b[0] == b'-';
    if sign { i = 1; }
    let mut dig = [0u8; 6];
    dig[0] = b[i] - b'0'; i += 2;              // d1 then '.'
    for k in 1..6 { dig[k] = b[i] - b'0'; i += 1; }
    debug_assert_eq!(b[i], b'e');
    let x: i32 = s[i + 1..].parse().unwrap();
    render(sign, &dig, x)
}

// ---- way B -------------------------------------------------------------
fn g_from_scratch(bits: u32) -> String {
    let sign = bits >> 31 == 1;
    let ebits = ((bits >> 23) & 0xFF) as i32;
    let frac = bits & 0x7F_FFFF;
    let (m, exp2) = if ebits == 0 { (frac, -149i32) } else { (frac | 0x80_0000, ebits - 150) };
    let mut dig = [0u8; 6];
    let x: i32;
    if m == 0 {
        x = 0;
    } else {
        // exact value = A * 10^(-s), A an exact integer held as decimal digits
        let mut a: Vec<u8> = m.to_string().bytes().map(|c| c - b'0').collect();
        let mul = |a: &mut Vec<u8>, k: u32| {
            let mut carry = 0u32;
            for d in a.iter_mut().rev() { let p = *d as u32 * k + carry; *d = (p % 10) as u8; carry = p / 10; }
            while carry > 0 { a.insert(0, (carry % 10) as u8); carry /= 10; }
        };
        let s: i32;
        if exp2 >= 0 { s = 0; for _ in 0..exp2 { mul(&mut a, 2); } }
        else { s = -exp2; for _ in 0..s { mul(&mut a, 5); } }
        let l = a.len() as i32;
        let x0 = l - 1 - s;
        if l <= P {
            for k in 0..(l as usize) { dig[k] = a[k]; }
            x = x0;
        } else {
            dig.copy_from_slice(&a[0..6]);
            let cmp = if a[6] > 5 { 1 } else if a[6] < 5 { -1 }
                      else if a[7..].iter().any(|&d| d != 0) { 1 } else { 0 };
            let up = cmp > 0 || (cmp == 0 && dig[5] % 2 == 1);
            let mut xx = x0;
            if up {
                let mut i = 5usize;
                loop {
                    if dig[i] != 9 { dig[i] += 1; break; }
                    dig[i] = 0;
                    if i == 0 { dig[0] = 1; xx = x0 + 1; break; }
                    i -= 1;
                }
            }
            x = xx;
        }
    }
    render(sign, &dig, x)
}

fn main() {
    let path = std::env::args().nth(1).unwrap();
    let f = BufReader::new(std::fs::File::open(&path).unwrap());
    let (mut n, mut bad_a, mut bad_b) = (0u64, 0u64, 0u64);
    for line in f.lines() {
