        if b != want { if bad_b < 10 { println!("B-MISMATCH {:08x} want={} got={}", bits, want, b); } bad_b += 1; }
    }
    println!("lines={} bad_via_rust_e={} bad_from_scratch={}", n, bad_a, bad_b);
}
